import{_ as t,b as a,e as r,a8 as o}from"./chunks/framework.CD0vREyi.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32","entity":"TCustomSampler","kind":"Class","declaration":"TCustomSampler = class(TNotifiablePersistent)","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TCustomSampler"],"summary":"Abstract base class representing color sampling engines capable of returning a `TColor32` at arbitrary sub-pixel floating-point coordinates (X, Y).","date":1787742964000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32/TCustomSampler/index.md","filePath":"api/GR32/TCustomSampler/index.md","lastUpdated":1787742964000,"timestamp":1787742964000,"datetime":"2026-08-26T11:16:04.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),s={name:"api/GR32/TCustomSampler/index.md"};function i(n,e,d,l,p,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TCustomSampler</code> is the abstract base class for all sampling engines in Graphics32. It provides a generalized interface for retrieving 32-bit ARGB color values (<code>TColor32</code>) at coordinate locations specified in integer, 16.16 fixed-point (<code>TFixed</code>), or single-precision floating-point (<code>TFloat</code>) formats.</p><p>Sampler implementations can represent procedurally generated patterns, color gradients, coordinate transformations, nested sampler chains, or bitmap resamplers.</p><p>Before performing intensive sampling loops, callers must call <code>PrepareSampling</code> to allow the sampler (and any nested child samplers) to initialize internal caches or lookup tables. After sampling is complete, <code>FinalizeSampling</code> should be called to release temporary resources.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Methods/GetSampleInt">GetSampleInt</a></td><td>Evaluates and returns a <code>TColor32</code> sample at integer coordinates (X, Y).</td></tr><tr><td><a href="./Methods/GetSampleFixed">GetSampleFixed</a></td><td>Evaluates and returns a <code>TColor32</code> sample at fixed-point 16.16 coordinates (X, Y).</td></tr><tr><td><a href="./Methods/GetSampleFloat">GetSampleFloat</a></td><td>Evaluates and returns a <code>TColor32</code> sample at floating-point coordinates (X, Y).</td></tr><tr><td><a href="./Methods/PrepareSampling">PrepareSampling</a></td><td>Prepares internal state, caches, and nested samplers before a sampling sequence begins.</td></tr><tr><td><a href="./Methods/FinalizeSampling">FinalizeSampling</a></td><td>Finalizes sampling state and cleans up temporary resources allocated during <code>PrepareSampling</code>.</td></tr><tr><td><a href="./Methods/HasBounds">HasBounds</a></td><td>Returns <code>True</code> if the sampler has defined spatial boundary limits.</td></tr><tr><td><a href="./Methods/GetSampleBounds">GetSampleBounds</a></td><td>Returns the spatial boundary rectangle (<code>TFloatRect</code>) within which valid samples exist.</td></tr></tbody></table>',6)])])}const u=t(s,[["render",i]]);export{h as __pageData,u as default};
